Here's how to handle each scenario with modern MSTest (3.9+/3.10+):

```csharp
[TestClass]
public sealed class PlatformAndEnvironmentTests
{
    private readonly TestContext _testContext;
    private string? _tempFilePath;

    public PlatformAndEnvironmentTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    // 1. Windows-only (skipped on Linux/macOS)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        using var key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\MyApp");
        Assert.IsNotNull(key);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void RenderFrame_UsesGpuAcceleration()
    {
        var result = GpuRenderer.RenderTestFrame();
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await WeatherClient.GetForecastAsync(
            "Seattle", _testContext.CancellationToken);
        Assert.IsNotNull(forecast);
    }

    // 4. Temp file cleanup — [TestCleanup] runs even on failure
    [TestMethod]
    public void Export_WritesValidFile()
    {
        _tempFilePath = Path.Combine(Path.GetTempPath(), $"{Guid.NewGuid()}.csv");

        Exporter.WriteCsv(_tempFilePath, new[] { "a", "b" });

        Assert.IsTrue(File.Exists(_tempFilePath));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFilePath is not null && File.Exists(_tempFilePath))
        {
            File.Delete(_tempFilePath);
        }
    }
}
```

**Summary of attributes:**

| Scenario | Attribute | Minimum Version |
|----------|-----------|-----------------|
| OS-specific | `[OSCondition(OperatingSystems.Windows)]` | MSTest 3.10+ |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` | MSTest 3.10+ |
| Flaky retry | `[Retry(3)]` | MSTest 3.9+ |
| Cleanup on failure | `[TestCleanup]` method | All versions |

**Key points:**
- `[OSCondition]` and `[CICondition]` cause tests to be *skipped* (not failed) when conditions aren't met.
- `[Retry]` should only be used for genuinely flaky external dependencies — not to mask race conditions.
- `[TestCleanup]` always runs after each test method, even if the test throws — making it ideal for resource cleanup.
